#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int ROOT = 15311432;
const int INVROOT = 469870224;

int reverseBits(int n, int k) {
    int res = 0;
    for (int i = 0; i < k; i++) {
        res = (res << 1) | (n & 1);
        n >>= 1;
    }
    return res;
}

long long modInverse(long long a) {
    long long result = 1, base = a, p = MOD - 2;
    while (p > 0) {
        if (p & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        p >>= 1;
    }
    return result;
}

long long modPow(long long a, long long p) {
    long long result = 1, base = a;
    while (p > 0) {
        if (p & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        p >>= 1;
    }
    return result;
}

void fft(vector<long long>& array, int logN, bool invert) {
    int baseRoot = invert ? INVROOT : ROOT;
    long long root = modPow(baseRoot, (1 << (23 - logN)));
    vector<long long> roots(logN);
    roots[logN - 1] = root;
    for (int i = logN - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    for (int s = 0; s < logN; s++) {
        int len = 1 << s;
        for (int start = 0; start < (int)array.size(); start += 2 * len) {
            long long curRoot = 1;
            for (int j = start; j < start + len; j++) {
                long long t = (curRoot * array[j + len]) % MOD;
                long long u = array[j];
                array[j] = (u + t) % MOD;
                array[j + len] = (u - t + MOD) % MOD;
                curRoot = (roots[s] * curRoot) % MOD;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> nums(m);
    for (int i = 0; i < m; i++) {
        cin >> nums[i];
    }
    sort(nums.begin(), nums.end());
    int minSize = n * nums[m - 1] + 2;
    int size = 1, logSize = 0;
    while (size < minSize) {
        size <<= 1;
        logSize++;
    }
    vector<long long> a(size, 0);
    for (int num : nums) {
        a[reverseBits(num, logSize)] = 1;
    }
    fft(a, logSize, false);
    for (int i = 0; i < size; i++) {
        a[i] = modPow(a[i], n);
    }
    vector<long long> temp(size, 0);
    for (int i = 0; i < size; i++) {
        temp[reverseBits(i, logSize)] = a[i] % MOD;
    }
    a = temp;
    fft(a, logSize, true);
    long long sumSquares = 0;
    for (int i = 0; i < size; i++) {
        sumSquares = (sumSquares + a[i] * a[i]) % MOD;
    }
    long long invSize = modInverse(size);
    cout << (((sumSquares * invSize) % MOD) * invSize) % MOD << "\n";
    return 0;
}

